// One budget for disposable localStorage caches. Player state is never an
// eviction candidate; large cached payloads already have in-memory owners.
export const MAX_CACHE_CHARS = 2_000_000;
export const MAX_CACHE_ENTRIES = 128;
const RESCAN_MS = 30_000;
const inventories = new WeakMap();

export function isDisposableCacheKey(key) {
  return /^(?:degenerus:(?:display|records|profiles|jackpots|referrer|foil-claim-levels|wwxrp-draw-days):v\d+:|craps-window-(?:api|logs):v\d+:|dice-run-logs:v\d+:|sdgnrs-redemption-logs:v\d+:|gnrus-lifetime-funding-v\d+:)/.test(String(key));
}

function storageOf(storage) {
  try { return storage === undefined ? globalThis.localStorage : storage; }
  catch { return null; }
}

function quotaError(error) {
  return error?.name === 'QuotaExceededError' || error?.name === 'NS_ERROR_DOM_QUOTA_REACHED'
    || error?.code === 22 || error?.code === 1014;
}

// Size values once, then maintain small metadata on writes. Never parse/copy
// every cached JSON payload on every poll. Other tabs invalidate this index;
// direct legacy writes are also caught by the periodic/length checks.
function inventory(storage, force = false) {
  let state = inventories.get(storage);
  const length = Number(storage.length);
  if (!state || force || (Number.isFinite(length) && state.length !== length)
    || Date.now() - state.scannedAt >= RESCAN_MS) {
    const prior = state?.entries || new Map();
    const found = new Map();
    for (let i = 0; i < length; i++) {
      const key = storage.key(i);
      if (!isDisposableCacheKey(key)) continue;
      const raw = storage.getItem(key);
      if (raw != null) found.set(key, key.length + raw.length);
    }
    // Preserve oldest-write order within the session. Restored entries whose
    // write age is unknown go first; no persistent manifest can itself grow.
    const entries = new Map([...found].filter(([key]) => !prior.has(key)));
    for (const key of prior.keys()) if (found.has(key)) entries.set(key, found.get(key));
    state = { entries, chars: [...entries.values()].reduce((a, b) => a + b, 0),
      length, scannedAt: Date.now() };
    inventories.set(storage, state);
  }
  return state;
}

function remove(storage, state, key) {
  storage.removeItem(key);
  state.chars -= state.entries.get(key) || 0;
  state.entries.delete(key);
  state.length = Number(storage.length);
}

function evictOne(storage, state, except = null) {
  for (const key of state.entries.keys()) {
    if (key === except) continue;
    remove(storage, state, key);
    return true;
  }
  return false;
}

/** Bound restored caches at startup, even before a new cache is written. */
export function pruneCachedStorage(storage) {
  const target = storageOf(storage);
  if (!target) return 0;
  let removed = 0;
  try {
    const state = inventory(target, true);
    while (state.chars > MAX_CACHE_CHARS || state.entries.size > MAX_CACHE_ENTRIES) {
      if (!evictOne(target, state)) break;
      removed++;
    }
  } catch { /* blocked storage must not prevent startup */ }
  return removed;
}

/** Cache admission is optional. Never save half a log window or trim its rows. */
export function writeCacheStorage(key, value, storage) {
  if (!isDisposableCacheKey(key)) return false;
  const target = storageOf(storage);
  if (!target) return false;
  try {
    const raw = String(value);
    const chars = key.length + raw.length;
    let state = inventory(target);
    if (chars > MAX_CACHE_CHARS) {
      remove(target, state, key);
      return false;
    }
    let rescanned = false;
    for (;;) {
      while (state.chars - (state.entries.get(key) || 0) + chars > MAX_CACHE_CHARS
        || state.entries.size + (state.entries.has(key) ? 0 : 1) > MAX_CACHE_ENTRIES) {
        if (!evictOne(target, state, key)) return false;
      }
      try { target.setItem(key, raw); break; }
      catch (error) {
        if (!quotaError(error)) return false;
        // A browser can impose a smaller quota, or an older tab can fill it.
        // Reconcile once and make room only from the disposable allowlist.
        if (!rescanned) { state = inventory(target, true); rescanned = true; }
        if (!evictOne(target, state, key)) {
          remove(target, state, key);
          return false;
        }
      }
    }
    state.chars += chars - (state.entries.get(key) || 0);
    state.entries.delete(key);
    state.entries.set(key, chars);
    state.length = Number(target.length);
    return true;
  } catch { return false; }
}

/** Give durable player state priority over reconstructible cached data. */
export function writePlayerStorage(key, value, storage) {
  if (isDisposableCacheKey(key)) return writeCacheStorage(key, value, storage);
  const target = storageOf(storage);
  if (!target) return false;
  try {
    const raw = String(value);
    try { target.setItem(key, raw); return true; }
    catch (error) { if (!quotaError(error)) return false; }
    const state = inventory(target, true);
    while (evictOne(target, state)) {
      try {
        target.setItem(key, raw);
        state.length = Number(target.length);
        return true;
      } catch (error) { if (!quotaError(error)) return false; }
    }
  } catch { /* caller-owned session state remains available */ }
  return false;
}

globalThis.addEventListener?.('storage', (event) => {
  if (event.storageArea) inventories.delete(event.storageArea);
});
